using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "GottatinkeremallAchievementData", menuName = "Data/Achievements/GottatinkeremallAchievementData")]
public class GottatinkeremallAchievementData : AchievementData
{
	public List<string> gottatinkeremallCompanionsCollectedList;

	public void NewCompanionAcquiredAddToGottatinkeremallCompanionsCollectedList(CompanionData companionData)
	{
		gottatinkeremallCompanionsCollectedList.AddIfNotAlreadyOnList(companionData.name);
		if (gottatinkeremallCompanionsCollectedList.Count >= base.AchievementVariableAmount)
		{
			saveSystem.DeleteGottatinkeremallCompanionsCollectedListSaveString();
			Unlock();
			gottatinkeremallCompanionsCollectedList.Clear();
		}
	}
}
